CREATE TABLE IF NOT EXISTS dating_events_v57(id INTEGER PRIMARY KEY AUTOINCREMENT,creator_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT DEFAULT '',city TEXT DEFAULT '',starts_at TEXT NOT NULL,capacity INTEGER DEFAULT 100,status TEXT DEFAULT 'published',created_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS event_rsvps_v57(event_id INTEGER NOT NULL,user_id TEXT NOT NULL,status TEXT DEFAULT 'going',created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event_id,user_id));
